<script setup lang="ts">
import {computed,defineAsyncComponent,onErrorCaptured,ref} from 'vue'
import {clamp,useMotionAllowed} from './motion'
const Scene=defineAsyncComponent(()=>import('./FormationScene.vue'))
const presets:Record<string,number[]>={'4-3-3':[1,4,3,3],'4-4-2':[1,4,4,2],'3-5-2':[1,3,5,2]}
const shape=ref('4-3-3'),selected=ref(0),zone=ref(true),camera=ref(0),three=ref(false),threeFailed=ref(false),field=ref<SVGSVGElement>()
const motion=useMotionAllowed()
function lineup(){return presets[shape.value]!.flatMap((size,row)=>Array.from({length:size},(_,col)=>({x:9+row*26,y:(col+1)*64/(size+1)})))}
const markers=ref(lineup()),active=computed(()=>markers.value[selected.value]!)
function reset(){markers.value=lineup();selected.value=0}
function move(i:number,x:number,y:number){markers.value[i]={x:clamp(x,2,98),y:clamp(y,2,62)}}
let dragging:number|undefined
function start(e:PointerEvent,i:number){selected.value=i;dragging=i;(e.currentTarget as Element).setPointerCapture(e.pointerId)}
function drag(e:PointerEvent){if(dragging===undefined)return;const matrix=field.value?.getScreenCTM();if(!matrix)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());move(dragging,p.x,p.y)}
function key(e:KeyboardEvent,i:number){const p=markers.value[i]!;const d:Record<string,number[]>={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]};const shift=d[e.key];if(shift){e.preventDefault();selected.value=i;move(i,p.x+shift[0]!,p.y+shift[1]!)}}
onErrorCaptured(()=>{three.value=false;threeFailed.value=true;return false})
</script>
<template><section class="motion-desk"><p class="eyebrow">TACTICAL LAB / YOUR DRAWING BOARD</p><h3>Shape the eleven.</h3><div class="centre-controls"><label>Formation<select v-model="shape" aria-label="Formation" @change="reset"><option v-for="(_,name) in presets" :key="name">{{ name }}</option></select></label><button :aria-pressed="zone" @click="zone=!zone">Defensive zone</button><button v-if="motion&&!threeFailed" :aria-pressed="three" @click="three=!three">{{ three?'2D editor':'3D preview' }}</button><button @click="reset">Reset positions</button></div><div v-if="three&&motion" class="formation-3d"><Scene :markers="markers" :camera="camera" @failed="three=false;threeFailed=true" /></div><label v-if="three&&motion">Camera angle<input v-model.number="camera" type="range" min="-5" max="5" step=".1"></label><svg v-else ref="field" class="formation-field" viewBox="0 0 100 64" aria-label="Formation editor; use arrow keys on a player" @pointermove="drag" @pointerup="dragging=undefined" @pointercancel="dragging=undefined"><rect width="100" height="64" fill="#204338" /><rect v-if="zone" x="0" y="0" width="34" height="64" fill="#62e0f026" /><path d="M2 2H98V62H2ZM50 2V62M2 16H15V48H2M98 16H85V48H98" stroke="#a3c5aa" stroke-width=".45" fill="none" /><circle cx="50" cy="32" r="8" stroke="#a3c5aa" stroke-width=".45" fill="none" /><polyline :points="markers.map(p=>p.x+','+p.y).join(' ')" stroke="#bcff6377" stroke-width=".45" stroke-dasharray="1 1" fill="none" /><g v-for="(p,i) in markers" :key="i" role="button" tabindex="0" :data-player-id="'marker-'+(i+1)" :aria-label="'Move player '+(i+1)" :transform="'translate('+p.x+' '+p.y+')'" @focus="selected=i" @keydown="key($event,i)" @keydown.enter="selected=i" @keydown.space.prevent="selected=i" @pointerdown="start($event,i)"><circle r="3.3" :fill="selected===i?'#bcff63':'#f5fff5'" /><text text-anchor="middle" dy="1.1" fill="#0a1519" font-size="3">{{ i+1 }}</text></g></svg><div class="centre-controls"><label>Selected player<select v-model.number="selected"><option v-for="(_,i) in markers" :key="i" :value="i">Player {{ i+1 }}</option></select></label><label>Width<input type="range" min="2" max="62" :value="active.y" @input="move(selected,active.x,Number(($event.target as HTMLInputElement).value))"></label><label>Depth<input type="range" min="2" max="98" :value="active.x" @input="move(selected,Number(($event.target as HTMLInputElement).value),active.y)"></label></div><p>Drag a marker or use the arrow keys. Dashed lines are suggested links on your board, not measured passes.</p></section></template>
